export const ProgramProgramTypeKeyToLabel = {
  'Regular': 'Regular',
  'FrenchImmersion': 'French Immersion',
  'IndigenousEducation': 'Indigenous Education',
  'InclusiveEducation': 'Inclusive Education',
  'CareerEducation': 'Career Education'
} as const;
export type ProgramProgramTypeKey = keyof typeof ProgramProgramTypeKeyToLabel;

export interface Program {
  /**
   * @displayName Program ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Program Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  programName: string;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName Is Active
   * @validationRule Required for create/update operations
   */
  isActive: boolean;
  /**
   * @displayName Program Type
   * @validationRule Required for create/update operations
   */
  programTypeKey: ProgramProgramTypeKey;
}

export const _Program = 'Program' as const;